<template>
  <main class="certificate-site" :style="{ '--brand': meta?.primaryColor || '#245fc8' }">
    <section v-if="landing" class="certificate-state"><span class="certificate-eyebrow">观潮会集 · 证书服务</span><h1>证书查询与领取</h1><p class="certificate-description">每场会议都有独立的证书查询入口。<br />请打开会务组提供的会议专属链接，查询并领取您的证书。</p></section>
    <div v-else-if="loading" class="certificate-state" role="status">正在打开会议证书服务…</div>
    <section v-else-if="!meta" class="certificate-state"><h1>证书查询</h1><p role="alert">{{ error || '查询页面暂不可用' }}</p><button type="button" @click="load">重新加载</button></section>
    <template v-else>
      <header class="certificate-hero" :style="meta.hasBackground ? { backgroundImage: `linear-gradient(0deg, rgba(0,0,0,.7), rgba(0,0,0,.28)), url(${base}/${publicId}/background)` } : {}" :class="{ 'has-background': meta.hasBackground }"><span class="certificate-eyebrow">会议专属证书服务</span><h1>{{ meta.name }}</h1><p>{{ meta.title }}</p></header>
      <section class="certificate-content">
        <div v-if="meta.paused" class="certificate-message" role="status">本会议证书领取已暂停，请联系会务组。</div>
        <template v-else>
          <div v-if="!result"><h2>{{ meta.title }}</h2><p class="certificate-description">{{ meta.description }}</p><form @submit.prevent="search"><label v-if="meta.templates.length > 1">证书类型<select v-model="templateId" :disabled="busy"><option v-for="t in meta.templates" :key="t.id" :value="t.id">{{ t.name }}</option></select></label><label v-for="f in meta.queryFields" :key="f.key">{{ f.label }}<span v-if="f.required" aria-label="必填"> *</span><input v-model="values[f.key]" :required="f.required" :disabled="busy" :placeholder="`请输入${f.label}`" :maxlength="1000" autocomplete="off" /></label><button type="submit" :disabled="busy">{{ busy ? '正在查询…' : '查询并领取' }}</button></form></div>
          <div v-else class="certificate-result"><div class="certificate-found" role="status">{{ result.name }} · {{ result.type }}</div><img v-if="imageUrl" :src="imageUrl" :alt="`${result.name}的${result.type}`" class="certificate-image" /><p class="certificate-number">证书编号：{{ result.certificateNo }}</p><button type="button" :disabled="busy" @click="download">{{ busy ? '正在准备文件…' : result.allowRepeatDownload ? '保存证书图片' : originalReady ? '原图已领取' : '领取证书原图' }}</button><p class="certificate-save-hint">{{ originalReady || result.allowRepeatDownload ? '微信内可长按证书图片保存。浏览器也可使用上方按钮下载。' : '当前为预览图，点击上方按钮领取原图后，可长按保存。' }}</p><button type="button" class="certificate-secondary" :disabled="busy" @click="reset">返回查询</button></div>
          <p v-if="error" class="certificate-message" role="alert">{{ error }}</p><p v-if="status" class="certificate-save-hint" role="status">{{ status }}</p>
        </template>
        <footer><p>{{ meta.contact }}</p><span v-if="meta.startsAt || meta.endsAt">领取时间：{{ meta.startsAt ? time(meta.startsAt) : '发布后' }} 至 {{ meta.endsAt ? time(meta.endsAt) : '持续开放' }}</span></footer>
      </section>
    </template>
  </main>
</template>

<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from "vue";
interface Meta { name: string; title: string; description: string; contact: string; primaryColor: string; hasBackground: boolean; queryFields: { key: string; label: string; required: boolean }[]; templates: { id: string; name: string }[]; paused: boolean; startsAt: string | null; endsAt: string | null }
interface Result { name: string; certificateNo: string; type: string; token: string; expiresAt: string; allowRepeatDownload: boolean }
const devBase = import.meta.env.DEV ? import.meta.env.VITE_API_BASE_URL || "http://localhost:3001/api" : "/api";
const base = `${devBase.replace(/\/$/, '')}/certificates`;
const match = window.location.pathname.match(/^\/c\/([A-Za-z0-9_-]{1,64})\/?$/), publicId = match?.[1] || "";
const landing = window.location.pathname === "/";
const meta = ref<Meta | null>(null), result = ref<Result | null>(null), imageUrl = ref(""), values = ref<Record<string, string>>({}), templateId = ref("");
const loading = ref(true), busy = ref(false), error = ref(""), status = ref(""), originalReady = ref(false);
let sequence = 0, controller: AbortController | undefined;
const time = (s: string) => new Date(s).toLocaleString("zh-CN", { timeZone: "Asia/Shanghai" });
async function request(path: string, body?: unknown, image = false) {
  const response = await fetch(`${base}/${publicId}${path}`, { method: body === undefined ? "GET" : "POST", headers: body === undefined ? {} : { "Content-Type": "application/json" }, ...(body === undefined ? {} : { body: JSON.stringify(body) }), cache: "no-store", signal: controller?.signal });
  if (image && response.ok) return response.blob();
  const payload = await response.json().catch(() => ({}));
  if (!response.ok || payload.code !== "OK") throw new Error(response.status >= 500 ? "服务暂不可用，请稍后重试。" : Array.isArray(payload.message) ? payload.message.join("；") : payload.message || "请求失败，请重试。");
  return payload.data;
}
function clearImage() { if (imageUrl.value) URL.revokeObjectURL(imageUrl.value); imageUrl.value = ""; }
function reset() { ++sequence; controller?.abort(); controller = undefined; clearImage(); result.value = null; error.value = ""; status.value = ""; originalReady.value = false; busy.value = false; }
async function load() { reset(); loading.value = true; try { if (!publicId) throw new Error("请使用会议提供的专属证书查询链接。"); meta.value = await request("") as Meta; templateId.value = meta.value.templates[0]?.id || ""; document.title = `${meta.value.name} · 证书查询`; } catch (e) { error.value = e instanceof Error ? e.message : "页面加载失败"; } finally { loading.value = false; } }
async function search() { if (busy.value) return; reset(); const current = ++sequence; controller = new AbortController(); busy.value = true; try { const found = await request("/search", { values: values.value, templateId: templateId.value }) as Result; const image = await request("/image", { token: found.token, download: false }, true) as Blob; if (current !== sequence) return; result.value = found; imageUrl.value = URL.createObjectURL(image); } catch (e) { if (current === sequence && !(e instanceof DOMException && e.name === "AbortError")) { result.value = null; clearImage(); error.value = e instanceof TypeError ? "网络连接失败，请检查网络后重试。" : e instanceof Error ? e.message : "查询失败"; } } finally { if (current === sequence) busy.value = false; } }
async function download() { if (!result.value || busy.value || originalReady.value && !result.value.allowRepeatDownload) return; busy.value = true; error.value = ""; try { const blob = await request("/image", { token: result.value.token, download: true }, true) as Blob; clearImage(); imageUrl.value = URL.createObjectURL(blob); const a = document.createElement("a"); a.href = imageUrl.value; a.download = `${result.value.certificateNo}.png`; document.body.appendChild(a); a.click(); a.remove(); originalReady.value = true; status.value = "证书原图已准备好；微信中可长按图片保存。"; } catch (e) { error.value = e instanceof Error ? e.message : "获取文件失败，请重试"; } finally { busy.value = false; } }
onMounted(() => { if (landing) { loading.value = false; document.title = "观潮会集 · 证书服务"; } else load(); }); onBeforeUnmount(() => { controller?.abort(); clearImage(); });
</script>

<style>
*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;color:#202a37;background:#f2f5f9}.certificate-site{max-width:760px;margin:40px auto;background:white;border-radius:16px;overflow:hidden;box-shadow:0 10px 40px rgba(25,45,80,.06);min-height:420px}.certificate-state{padding:64px 28px;text-align:center}.certificate-hero{padding:44px 40px 36px;background:color-mix(in srgb,var(--brand) 9%,white);background-position:center;background-size:cover}.certificate-eyebrow{font-size:12px;letter-spacing:2px;color:#56657a}.certificate-hero h1{font-size:30px;line-height:1.45;margin:12px 0 14px;overflow-wrap:anywhere}.certificate-hero p{font-size:15px;line-height:1.7;margin:0;color:#56657a}.certificate-hero.has-background,.certificate-hero.has-background p,.certificate-hero.has-background .certificate-eyebrow{color:#fff}.certificate-content{padding:36px 40px}.certificate-content h2{font-size:21px;margin:0 0 14px}.certificate-description{font-size:14px;line-height:1.8;color:#586679;white-space:pre-wrap;margin-bottom:25px}.certificate-site form label{display:block;font-size:14px;margin:18px 0}.certificate-site input,.certificate-site select{display:block;width:100%;padding:12px 14px;border:1px solid #ccd5e0;border-radius:7px;font:inherit;font-size:16px;margin-top:8px;background:#fff;color:#202a37}.certificate-site button{display:block;width:100%;min-height:48px;padding:12px 18px;background:var(--brand);color:#fff;border:1px solid var(--brand);border-radius:7px;font:inherit;font-size:15px;cursor:pointer}.certificate-site button:disabled{opacity:.6;cursor:default}.certificate-message{padding:14px 16px;background:#fff6e8;color:#815a17;border-radius:7px;font-size:14px;line-height:1.8;margin-top:18px}.certificate-content footer{margin-top:36px;padding-top:20px;border-top:1px solid #e6ebf1;font-size:12px;color:#677487;line-height:1.8;white-space:pre-wrap}.certificate-image{display:block;width:100%;height:auto;border:1px solid #e1e6ed;margin:20px 0;user-select:auto}.certificate-found{color:#28774d;background:#eef8f2;padding:12px 16px;font-size:14px;border-radius:7px}.certificate-number{font-size:13px;color:#5b687b;overflow-wrap:anywhere}.certificate-save-hint{font-size:12px;color:#607086;line-height:1.8;margin:14px 0}.certificate-site .certificate-secondary{background:white;color:var(--brand);margin-top:16px}.certificate-site button:focus-visible,.certificate-site input:focus-visible,.certificate-site select:focus-visible{outline:3px solid color-mix(in srgb,var(--brand) 50%,white);outline-offset:2px}@media(max-width:600px){body{background:#fff}.certificate-site{margin:0 auto;border-radius:0;box-shadow:none;min-height:100vh}.certificate-hero{padding:36px 24px 28px}.certificate-hero h1{font-size:25px}.certificate-content{padding:28px 24px}}@media(max-width:350px){.certificate-hero,.certificate-content{padding-left:18px;padding-right:18px}}
</style>
